// embed_ca_bundle.cpp -- build-time helper that turns a PEM bundle into a C++
// translation unit, so the TLS roots live inside the binary.
//
// usage: tea_embed_ca_bundle <output-dir> <pem-path>
//
// A missing <pem-path> is not an error: the generated file then reports an
// empty bundle, and tea_agent falls back to looking for a file at runtime. That
// keeps "build without vendored roots" a supported configuration instead of a
// build failure.
//
// Deliberately depends on nothing but the C++ standard library, so it builds
// with any host compiler including the old ones used for cross builds.

#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <sstream>
#include <string>

namespace {

std::string read_binary(const std::string& path, bool* ok) {
  std::ifstream in(path.c_str(), std::ios::binary);
  if (!in) {
    *ok = false;
    return std::string();
  }
  std::ostringstream ss;
  ss << in.rdbuf();
  *ok = true;
  return ss.str();
}

/// The PEM is plain ASCII, so a raw string literal is the compact choice. The
/// delimiter is fixed and checked: if it ever appeared in the data we would
/// terminate the literal early.
const char* kDelim = "TEA_CA_BUNDLE";

bool raw_literal_is_safe(const std::string& data) {
  const std::string terminator = std::string(")") + kDelim + "\"";
  return data.find(terminator) == std::string::npos;
}

std::string escaped_literal(const std::string& data) {
  std::string out = "\"";
  char buf[16];
  for (std::size_t i = 0; i < data.size(); ++i) {
    const unsigned char c = static_cast<unsigned char>(data[i]);
    switch (c) {
      case '\\': out += "\\\\"; break;
      case '"': out += "\\\""; break;
      case '\n': out += "\\n"; break;
      case '\r': out += "\\r"; break;
      case '\t': out += "\\t"; break;
      default:
        if (c < 0x20 || c == 0x7f) {
          // Reopen the literal so a following hex digit cannot be swallowed.
          std::snprintf(buf, sizeof(buf), "\\x%02x\" \"", c);
          out += buf;
        } else {
          out += static_cast<char>(c);
        }
    }
  }
  out += "\"";
  return out;
}

}  // namespace

int main(int argc, char** argv) {
  if (argc < 3) {
    std::fprintf(stderr, "usage: tea_embed_ca_bundle <output-dir> <pem-path>\n");
    return 2;
  }
  const std::string out_dir = argv[1];
  const std::string pem_path = argv[2];

  bool ok = false;
  const std::string pem = read_binary(pem_path, &ok);
  if (!ok) {
    std::fprintf(stderr, "embed_ca_bundle: %s not found; embedding an empty bundle\n",
                 pem_path.c_str());
  } else if (pem.find("-----BEGIN CERTIFICATE-----") == std::string::npos) {
    std::fprintf(stderr, "embed_ca_bundle: %s contains no PEM certificates; embedding an empty bundle\n",
                 pem_path.c_str());
    ok = false;
  }

  std::ostringstream out;
  out << "// Generated by tools/embed_ca_bundle.cpp -- do not edit.\n";
  out << "//\n";
  out << "// The trusted roots are compiled into the binary so a single-file\n";
  out << "// deployment has working TLS without shipping a sidecar PEM next to it.\n";
  out << "#include <cstddef>\n\n";
  out << "#include \"ca_bundle.h\"\n\n";
  out << "namespace tea {\nnamespace {\n";
  if (ok) {
    if (raw_literal_is_safe(pem)) {
      out << "const char kPem[] = R\"" << kDelim << "(" << pem << ")" << kDelim << "\";\n";
    } else {
      out << "const char kPem[] = " << escaped_literal(pem) << ";\n";
    }
  } else {
    out << "const char kPem[] = \"\";\n";
  }
  out << "}  // namespace\n\n";
  out << "const char* embedded_ca_bundle_pem() { return kPem[0] ? kPem : nullptr; }\n";
  out << "std::size_t embedded_ca_bundle_size() {\n";
  out << "  return kPem[0] ? sizeof(kPem) - 1 : 0;\n";
  out << "}\n\n}  // namespace tea\n";

  const std::string path = out_dir + "/ca_bundle.cpp";
  std::ofstream f(path.c_str(), std::ios::binary);
  if (!f) {
    std::fprintf(stderr, "embed_ca_bundle: cannot write %s\n", path.c_str());
    return 2;
  }
  const std::string text = out.str();
  f.write(text.data(), static_cast<std::streamsize>(text.size()));
  if (!f) {
    std::fprintf(stderr, "embed_ca_bundle: failed writing %s\n", path.c_str());
    return 2;
  }
  if (ok) {
    std::fprintf(stderr, "embed_ca_bundle: embedded %lu bytes of PEM from %s\n",
                 static_cast<unsigned long>(pem.size()), pem_path.c_str());
  }
  return 0;
}
